from workflows.events import StartEvent, StopEvent, Event
class Again(Event):
    v: int
class W(Workflow):
    @step
    async def start(self, ev: StartEvent) -> Again:
        return Again(v=ev.n)
    @step
    async def grow(self, ctx: Context, ev: Again) -> Again | StopEvent:
        loops = await ctx.store.get("loops", default=0)
        await ctx.store.set("loops", loops + 1)
        if ev.v >= 16:
            return StopEvent(result=(ev.v, loops + 1))
        return Again(v=ev.v + 4)
async def main():
    return await W(timeout=10).run(n=1)
print(asyncio.run(main()))

