import asyncio
from workflows import Workflow, step, Context
from workflows.events import StartEvent, StopEvent, Event
class Small(Event):
    v: int
class Big(Event):
    v: int
class W(Workflow):
    @step
    async def route(self, ev: StartEvent) -> Small | Big:
        return Big(v=ev.n) if ev.n >= 4 else Small(v=ev.n)
    @step
    async def small(self, ev: Small) -> StopEvent:
        return StopEvent(result=f"small:{ev.v}")
    @step
    async def big(self, ev: Big) -> StopEvent:
        return StopEvent(result=f"big:{ev.v}")
async def main():
    return await W(timeout=10).run(n=10)
print(asyncio.run(main()))

import asyncio
from workflows import Workflow, step, Context
from workflows.events import StartEvent, StopEvent, Event
class Again(Event):
    v: int
class W(Workflow):
    @step
    async def start(self, ev: StartEvent) -> Again:
        return Again(v=ev.n)
    @step
    async def grow(self, ctx: Context, ev: Again) -> Again | StopEvent:
        loops = await ctx.store.get("loops", default=0)
        await ctx.store.set("loops", loops + 1)
        if ev.v >= 17:
            return StopEvent(result=(ev.v, loops + 1))
        return Again(v=ev.v + 3)
async def main():
    return await W(timeout=10).run(n=1)
print(asyncio.run(main()))

